-/** Convert `value` from one unit to another of the same kind. See README.md. */
+import { LINEAR_UNITS, TEMPERATURE_UNITS } from "./units.ts";
+
+function isLinear(symbol: string): boolean {
+  return symbol in LINEAR_UNITS;
+}
+
+function isTemperature(symbol: string): boolean {
+  return (TEMPERATURE_UNITS as readonly string[]).includes(symbol);
+}
+
+function checkAbsoluteZero(value: number, unit: string): void {
+  switch (unit) {
+    case "C":
+      if (value < -273.15) throw new RangeError("temperature below absolute zero");
+      break;
+    case "F":
+      if (value < -459.67) throw new RangeError("temperature below absolute zero");
+      break;
+    case "K":
+      if (value < 0) throw new RangeError("temperature below absolute zero");
+      break;
+  }
+}
+
+function toCelsius(value: number, from: string): number {
+  switch (from) {
+    case "C": return value;
+    case "F": return (value - 32) * 5 / 9;
+    case "K": return value - 273.15;
+    default: throw new Error("unknown unit: " + from);
+  }
+}
+
+function fromCelsius(celsius: number, to: string): number {
+  switch (to) {
+    case "C": return celsius;
+    case "F": return celsius * 9 / 5 + 32;
+    case "K": return celsius + 273.15;
+    default: throw new Error("unknown unit: " + to);
+  }
+}
